// ── Inline row ────────────────────────────────────────────────────────────────
function DocRow({entry,onSave,onDelete,onInsertAfter,onEdit,idx,otherItems,billingMatch,insOpen,onToggleIns}) {
  const [form,setForm]=useState({...entry});
  const formRef=useRef({...entry});

  const set=useCallback((k,v)=>{
    setForm(prev=>{const next={...prev,[k]:v};formRef.current=next;return next;});
  },[]);

  // Sync attn from entry prop when it changes (e.g. after page reload)
  useEffect(()=>{
    if (entry.attn !== formRef.current.attn) {
      setForm(prev=>({...prev,attn:entry.attn}));
      formRef.current={...formRef.current,attn:entry.attn};
    }
  },[entry.attn]);

  useEffect(()=>{
    if (billingMatch) {
      const updates={};
      if (billingMatch.insurancePaid1&&billingMatch.insurancePaid1!==formRef.current.insurancePaid1) updates.insurancePaid1=billingMatch.insurancePaid1;
      if (billingMatch.insurancePaid2&&billingMatch.insurancePaid2!==formRef.current.insurancePaid2) updates.insurancePaid2=billingMatch.insurancePaid2;
      // Sync billing notes to row for visibility
      if (billingMatch.notes&&billingMatch.notes!==formRef.current.billingNotes) updates.billingNotes=billingMatch.notes;
      if (Object.keys(updates).length>0) {
        setForm(prev=>({...prev,...updates}));
        formRef.current={...formRef.current,...updates};
      }
    }
  },[billingMatch?.insurancePaid1,billingMatch?.insurancePaid2,billingMatch?.notes]); // eslint-disable-line

  const save=useCallback(async()=>{
    const f=formRef.current;
    if (!f.patientName?.trim()) return;
    const upd={...f,updatedAt:new Date().toISOString()};
    await setDoc(doc(db,'doctorLogs',f.id),upd);
    onSave(upd);
  },[onSave]);

  const ptPaid=calcPtPaid(form);
  const ins1Exp=parseFloat(form.ins1Amt)||0;
  const ins2Exp=parseFloat(form.ins2Amt)||0;
  const ins1Paid=parseFloat(form.insurancePaid1)||0;
  const ins2Paid=parseFloat(form.insurancePaid2)||0;
  const ins3Exp=parseFloat(form.ins3Amt)||0;
  const ins3Paid=parseFloat(form.insurancePaid3)||0;
  const total=ptPaid+(ins1Paid>0?ins1Paid:ins1Exp)+(ins2Paid>0?ins2Paid:ins2Exp)+(ins3Paid>0?ins3Paid:ins3Exp);
  const isUnpaid=form.entryType==='followup';
  const rowBg=form.attn?'#FFF7ED':isUnpaid?'#FFFBEB':idx%2===0?'white':'#F8FAFC';

  // Keyboard navigation using refs
  const fieldRefs = useRef({});
  const FIELD_ORDER = ['patientName','exam','cl','optos','oct','dfe','ov','myopia','otherAmt','otherType','discountAmount','discountType','payor1','ins1Amt','payor2','ins2Amt','notes'];
  const onKey = (e, field) => {
    if (e.key === 'Tab') {
      // Let Tab work natively on selects — only intercept on text inputs
      if (e.target.tagName === 'SELECT') return;
      e.preventDefault();
      const i = FIELD_ORDER.indexOf(field);
      const nextField = e.shiftKey ? FIELD_ORDER[i-1] : FIELD_ORDER[i+1];
      if (nextField && fieldRefs.current[nextField]) fieldRefs.current[nextField].focus();
    }
  };
  const ref = (field) => el => { if (el) fieldRefs.current[field] = el; };

  const ns=(w)=>({width:w||32,padding:'2px 2px',border:'1px solid #E2E8F0',borderRadius:3,fontSize:11,textAlign:'right',fontFamily:"'DM Sans',sans-serif",background:'transparent'});
  const ts=(w)=>({...ns(w),textAlign:'left'});
  const numInp=(key,w)=>(
    <input type="text" inputMode="decimal" value={form[key]||''} placeholder=""
      style={ns(w||32)} onChange={e=>set(key,e.target.value)} onBlur={save}
      ref={ref(key)} onKeyDown={e=>onKey(e,key)}/>
  );

  return (
    <>
    <tr style={{background:rowBg,borderBottom:'1px solid #F0F4F8'}}>
      {/* Loc */}
      <td style={{padding:'2px 3px',whiteSpace:'nowrap'}}>
        {form.location&&<span style={{background:(LOC_COLORS[form.location]||'#94A3B8')+'25',color:LOC_COLORS[form.location]||'#64748B',borderRadius:3,padding:'1px 4px',fontSize:9,fontWeight:700}}>{form.location}</span>}
      </td>
      {/* Day */}
      <td style={{padding:'2px 2px',fontSize:10,color:'#94A3B8',whiteSpace:'nowrap'}}>{dayAbb(form.date)}</td>
      {/* Date */}
      <td style={{padding:'2px 3px',fontSize:10,color:'#64748B',whiteSpace:'nowrap'}}>{fmtShort(form.date)}</td>
      {/* Patient */}
      <td style={{padding:'2px 3px'}}>
        <input value={form.patientName||''} onChange={e=>set('patientName',e.target.value)} onBlur={save}
          placeholder="Patient name" style={{...ts(115),width:115}} ref={ref('patientName')} onKeyDown={e=>onKey(e,'patientName')}/>
      </td>
      {/* Unpaid */}
      <td style={{padding:'2px 4px',textAlign:'center'}}>
        <input type="checkbox" checked={isUnpaid} title="Check for follow-ups or visits with no charge"
          onChange={e=>{set('entryType',e.target.checked?'followup':'paid');setTimeout(save,50);}}
          style={{cursor:'pointer',width:12,height:12,accentColor:'#92400E'}}/>
      </td>
      {/* Services */}
      {['exam','cl','optos','oct','dfe','ov'].map(k=>(
        <td key={k} style={{padding:'2px 1px'}}>{numInp(k,32)}</td>
      ))}
      <td style={{padding:'2px 1px'}}>{numInp('myopia',32)}</td>
      {/* Other $ + type */}
      <td style={{padding:'2px 1px'}}>{numInp('otherAmt',32)}</td>
      <td style={{padding:'2px 1px'}}>
        <select value={form.otherType||''} style={{...ts(68),padding:'2px 2px',cursor:'pointer'}}
          onChange={e=>{set('otherType',e.target.value);setTimeout(save,50);}}>
          <option value="">—</option>
          {(otherItems||[]).map(o=><option key={o}>{o}</option>)}
        </select>
      </td>
      {/* Disc $ + type */}
      <td style={{padding:'2px 1px'}}>{numInp('discountAmount',32)}</td>
      <td style={{padding:'2px 1px'}}>
        <select value={form.discountType||''} style={{...ts(68),padding:'2px 2px',cursor:'pointer'}}
          onChange={e=>{set('discountType',e.target.value);setTimeout(save,50);}}>
          <option value="">—</option>
          {DISCOUNT_TYPES.map(t=><option key={t}>{t}</option>)}
        </select>
      </td>
      {/* Pt Paid */}
      <td style={{padding:'2px 2px',fontSize:11,fontWeight:700,color:'#16A34A',textAlign:'right',whiteSpace:'nowrap'}}>{ptPaid>0?fmt$(ptPaid):'—'}</td>
      {/* Total */}
      <td style={{padding:'2px 2px',fontSize:11,fontWeight:700,color:'#1B3A5C',textAlign:'right',whiteSpace:'nowrap'}}>{total>0?fmt$(total):'—'}</td>
      {/* P1$ */}
      <td style={{padding:'2px 1px',background:ins1Paid>0?'#F0FDF4':ins1Exp>0?'#FFFBEB':'transparent'}}>
        {numInp('ins1Amt',32)}
      </td>
      {/* P1 */}
      <td style={{padding:'2px 1px'}}>
        <select value={form.payor1||''} style={{...ts(54),padding:'2px 2px',cursor:'pointer'}}
          ref={ref('payor1')} onChange={e=>{set('payor1',e.target.value);setTimeout(save,50);}}>
          <option value="">—</option>{PAYORS.map(p=><option key={p.value} value={p.value}>{p.label}</option>)}
        </select>
      </td>
      {/* Notes */}
      <td style={{padding:'2px 1px',width:'auto'}}>
        <input value={form.notes||''} onChange={e=>set('notes',e.target.value)} onBlur={save}
          placeholder="Notes" style={{...ts(100),width:'100%',minWidth:60,boxSizing:'border-box'}} ref={ref('notes')} onKeyDown={e=>onKey(e,'notes')}/>
        {form.billingNotes&&<span title={`Billing note: ${form.billingNotes}`} style={{position:'absolute',top:2,right:2,fontSize:8,color:'#1D4ED8',cursor:'help'}}>ℹ</span>}
      </td>
      {/* All controls — single sticky td */}
      <td style={{padding:'2px 4px',whiteSpace:'nowrap',position:'sticky',right:0,
        background:form.attn?'#FFF7ED':isUnpaid?'#FFFBEB':idx%2===0?'#FFFFFF':'#F8FAFC',
        zIndex:2,borderLeft:'1px solid #E2E8F0'}}>
        <div style={{display:'flex',alignItems:'center',gap:4}}>
          <button onClick={()=>{set('attn',form.attn?'':'★');setTimeout(save,50);}}
            style={{background:'none',border:'none',cursor:'pointer',fontSize:16,padding:0,lineHeight:1,
              color:form.attn?'#F59E0B':'#D1D5DB'}} title={form.attn?'Flagged — click to remove':'Flag for biller'}>★</button>
          <button onClick={e=>{e.stopPropagation();onToggleIns();}}
            style={{background:insOpen?'#E0F2FE':'#F1F5F9',border:'none',borderRadius:3,padding:'1px 4px',cursor:'pointer',fontSize:9,color:insOpen?'#0891B2':'#94A3B8'}}>{insOpen?'▲':'▼'}</button>
          <button onClick={()=>onInsertAfter()}
            style={{background:'#F0FDF4',border:'none',borderRadius:3,padding:'1px 4px',cursor:'pointer',fontSize:10,color:'#16A34A'}}>+</button>
          <button onClick={()=>onDelete(entry.id)}
            style={{background:'#FEE2E2',border:'none',borderRadius:3,padding:'1px 4px',cursor:'pointer',fontSize:10,color:'#DC2626'}}>✕</button>
        </div>
      </td>
    </tr>
    {/* Expanded sub-row: Other2, P2/P3, Claims */}
    {insOpen&&(
      <tr style={{background:'#F0F9FF',borderBottom:'1px solid #BAE6FD'}}>
        <td colSpan={5} style={{padding:'3px 6px'}}></td>
        <td colSpan={19} style={{padding:'4px 8px'}}>
          <div style={{display:'flex',gap:10,flexWrap:'wrap',alignItems:'flex-end',fontSize:10}}>
            {/* Other 2 */}
            <div style={{display:'flex',flexDirection:'column',gap:2}}>
              <span style={{fontSize:8,color:'#64748B',fontWeight:700,textTransform:'uppercase'}}>Other 2</span>
              <div style={{display:'flex',gap:3}}>
                <input type="text" inputMode="decimal" value={form.otherAmt2||''} onChange={e=>set('otherAmt2',e.target.value)} onBlur={save}
                  style={{width:40,padding:'2px 3px',border:'1px solid #BAE6FD',borderRadius:3,fontSize:10,textAlign:'right'}} placeholder="$"/>
                <select value={form.otherType2||''} style={{fontSize:10,padding:'2px 3px',border:'1px solid #BAE6FD',borderRadius:3,background:'white',cursor:'pointer',width:80}}
                  onChange={e=>{set('otherType2',e.target.value);setTimeout(save,50);}}>
                  <option value="">—</option>{(otherItems||[]).map(o=><option key={o}>{o}</option>)}
                </select>
              </div>
            </div>
            {/* P2 */}
            <div style={{display:'flex',flexDirection:'column',gap:2}}>
              <span style={{fontSize:8,color:'#1D4ED8',fontWeight:700,textTransform:'uppercase'}}>P2</span>
              <div style={{display:'flex',gap:3}}>
                <input type="text" inputMode="decimal" value={form.ins2Amt||''} onChange={e=>set('ins2Amt',e.target.value)} onBlur={save}
                  style={{width:40,padding:'2px 3px',border:'1px solid #BAE6FD',borderRadius:3,fontSize:10,textAlign:'right',background:ins2Paid>0?'#F0FDF4':ins2Exp>0?'#FFFBEB':'white'}} placeholder="$"/>
                <select value={form.payor2||''} style={{fontSize:10,padding:'2px 3px',border:'1px solid #BAE6FD',borderRadius:3,background:'white',cursor:'pointer',width:64}}
                  onChange={e=>{set('payor2',e.target.value);setTimeout(save,50);}}>
                  <option value="">—</option>{PAYORS.map(p=><option key={p.value} value={p.value}>{p.label}</option>)}
                </select>
              </div>
            </div>
            {/* P3 */}
            <div style={{display:'flex',flexDirection:'column',gap:2}}>
              <span style={{fontSize:8,color:'#1D4ED8',fontWeight:700,textTransform:'uppercase'}}>P3</span>
              <div style={{display:'flex',gap:3}}>
                <input type="text" inputMode="decimal" value={form.ins3Amt||''} onChange={e=>set('ins3Amt',e.target.value)} onBlur={save}
                  style={{width:40,padding:'2px 3px',border:'1px solid #BAE6FD',borderRadius:3,fontSize:10,textAlign:'right'}} placeholder="$"/>
                <select value={form.payor3||''} style={{fontSize:10,padding:'2px 3px',border:'1px solid #BAE6FD',borderRadius:3,background:'white',cursor:'pointer',width:64}}
                  onChange={e=>{set('payor3',e.target.value);setTimeout(save,50);}}>
                  <option value="">—</option>{PAYORS.map(p=><option key={p.value} value={p.value}>{p.label}</option>)}
                </select>
              </div>
            </div>
            {/* Claims */}
            {[['Claim #1','claimNumber'],['Claim #2','claimNumber2'],['Claim #3','claimNumber3']].map(([label,key])=>(
              <div key={key} style={{display:'flex',flexDirection:'column',gap:2}}>
                <span style={{fontSize:8,color:'#64748B',fontWeight:700,textTransform:'uppercase'}}>{label}</span>
                <input type="text" value={form[key]||''} onChange={e=>set(key,e.target.value)} onBlur={save}
                  style={{width:80,padding:'2px 3px',border:'1px solid #BAE6FD',borderRadius:3,fontSize:10}}/>
              </div>
            ))}
            <button onClick={()=>onToggleIns()} style={{marginLeft:'auto',background:'none',border:'none',cursor:'pointer',fontSize:10,color:'#0891B2',alignSelf:'center'}}>✕</button>
          </div>
        </td>
      </tr>
    )}
    </>
  );
}

// ── Square Panel ──────────────────────────────────────────────────────────────
function DocSquarePanel({date,loc,rows,inline=false}) {
  const [txns,setTxns]=useState(null);
  const [loading,setLoading]=useState(false);
  const [open,setOpen]=useState(false);
  const [error,setError]=useState('');
  const [squareNotes,setSquareNotes]=useState({}); // txnId -> {note, preMatch}

  // Load persisted notes/prematches from Firestore
  const loadNotes=async()=>{
    try{
      const { getDocs:gd, collection:col, query:q, where:wh } = await import('firebase/firestore');
      const snap=await gd(q(col(db,'squareNotes'),wh('date','==',date||'')));
      const map={};
      snap.docs.forEach(d=>{map[d.data().txnId]={note:d.data().note||'',preMatch:d.data().preMatch||''};});
      setSquareNotes(map);
    }catch(e){console.error(e);}
  };

  const saveNote=async(txnId,updates)=>{
    const current=squareNotes[txnId]||{};
    const merged={...current,...updates};
    setSquareNotes(p=>({...p,[txnId]:merged}));
    try{
      const {setDoc:sd,doc:fdoc}=await import('firebase/firestore');
      await sd(fdoc(db,'squareNotes',`sq_${txnId}`),{txnId,date:date||'',loc:loc||'',...merged,updatedAt:new Date().toISOString()});
    }catch(e){console.error('Note save error:',e);}
  };

  const load=async()=>{
    if(!date||!loc){alert('Please select a date and location first.');return;}
    setLoading(true);setError('');
    await loadNotes();
    try{
      const res=await fetch(SQUARE_WORKER,{method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({begin_time:`${date}T00:00:00-07:00`,end_time:`${date}T23:59:59-07:00`,_t:Date.now()})});
      if(!res.ok) throw new Error(`${res.status}`);
      const data=await res.json();
      setTxns((data.payments||[]).filter(p=>p.status==='COMPLETED'&&deviceToLoc(p.device_details?.device_name)===loc)
        .sort((a,b)=>(a.created_at||'').localeCompare(b.created_at||'')));
    }catch(e){setError(e.message);}
    setLoading(false);
  };

  if(!open) return (
    <button onClick={()=>{setOpen(true);if(date&&loc)load();}}
      style={{background:'#F0FDF4',border:'1px solid #6EE7B7',borderRadius:5,padding:'4px 12px',cursor:'pointer',fontSize:11,color:'#065F46',fontWeight:700,...(!inline?{marginBottom:8}:{}),display:'inline-flex',alignItems:'center',gap:4}}>
      💳 Square Payments
    </button>
  );

  return (
    <div style={{marginBottom:10,background:'#F8FFFE',border:'1px solid #6EE7B7',borderRadius:8,padding:'8px 12px'}}>
      <div style={{display:'flex',alignItems:'center',gap:6,marginBottom:6}}>
        <span style={{fontSize:12,fontWeight:700,color:'#065F46'}}>💳 Square — {date||'no date'} {loc||'no location'}</span>
        <button onClick={load} disabled={loading} style={{background:'#F0FDF4',border:'1px solid #6EE7B7',borderRadius:4,padding:'1px 7px',cursor:'pointer',fontSize:10,color:'#065F46'}}>{loading?'...':' ↺'}</button>
        <button onClick={()=>setOpen(false)} style={{marginLeft:'auto',background:'none',border:'none',cursor:'pointer',fontSize:13,color:'#94A3B8'}}>✕</button>
      </div>
      {error&&<div style={{fontSize:11,color:'#DC2626'}}>Error: {error}</div>}
      {loading&&<div style={{fontSize:11,color:'#94A3B8'}}>Loading...</div>}
      {txns&&txns.length===0&&<div style={{fontSize:11,color:'#94A3B8'}}>No completed transactions found.</div>}
      {txns&&txns.map(txn=>{
        const amt=(txn.amount_money?.amount||0)/100;
        const txnNote=txn.note||'';
        const time=fmtTime(txn.created_at);
        const isCash=txn.source_type==='CASH';
        const lineItems=txn.line_items||[];
        const savedData=squareNotes[txn.id]||{};
        const autoMatch=rows.filter(r=>r.patientName?.trim()).map(r=>({r,score:squareNameSim(txnNote,r.patientName)})).filter(r=>r.score>0.3).sort((a,b)=>b.score-a.score)[0]?.r;
        const linked=autoMatch&&(autoMatch.squareTransactionId===txn.id||(Array.isArray(autoMatch.squareTransactionIds)&&autoMatch.squareTransactionIds.includes(txn.id)));
        const preMatchName=savedData.preMatch||(autoMatch&&!linked?autoMatch.patientName:'');
        return (
          <div key={txn.id} style={{marginBottom:5,padding:'6px 8px',background:linked?'#F0FDF4':'white',borderRadius:5,border:`1px solid ${linked?'#6EE7B7':'#E2E8F0'}`}}>
            {/* Main row */}
            <div style={{display:'flex',alignItems:'center',gap:8,flexWrap:'wrap'}}>
              <span style={{fontSize:12,fontWeight:700,color:'#1B3A5C',whiteSpace:'nowrap'}}>{fmt$(amt)}</span>
              <span style={{fontSize:11,color:'#475569',whiteSpace:'nowrap'}}>{time}</span>
              {isCash&&<span style={{fontSize:9,background:'#FEF3C7',color:'#92400E',borderRadius:2,padding:'0 3px',fontWeight:700}}>CASH</span>}
              {lineItems.length>0&&<span style={{fontSize:11,color:'#475569'}}>{lineItems.map(i=>`${i.name} ${fmt$((i.base_price_money?.amount||0)/100*(i.quantity||1))}`).join(' · ')}</span>}
              {txnNote&&<span style={{fontSize:11,color:'#64748B',fontStyle:'italic'}}>"{txnNote}"</span>}
              {/* Patient match inline */}
              <div style={{marginLeft:'auto',display:'flex',alignItems:'center',gap:4}}>
                {linked?(
                  <span style={{fontSize:11,color:'#065F46',fontWeight:700}}>✓ {autoMatch.patientName}</span>
                ):(
                  <select value={preMatchName} onChange={e=>saveNote(txn.id,{preMatch:e.target.value})}
                    title="Who is this patient?"
                    style={{fontSize:10,padding:'1px 3px',border:'1px solid #E2E8F0',borderRadius:4,background:'white',maxWidth:130,color:preMatchName?'#1B3A5C':'#94A3B8'}}>
                    <option value="">— Match patient —</option>
                    {rows.filter(r=>r.patientName?.trim()).map(r=><option key={r.id} value={r.patientName}>{r.patientName}</option>)}
                  </select>
                )}
                <NoteInline txnId={txn.id} initial={savedData.note||''} onSave={note=>saveNote(txn.id,{note})}/>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

function NoteInline({txnId,initial,onSave}) {
  const [val,setVal]=useState(initial||'');
  const [editing,setEditing]=useState(false);
  useEffect(()=>setVal(initial||''),[initial]);
  if (!editing&&!val) return (
    <button onClick={()=>setEditing(true)} title="Add a note for your biller (e.g. split visit, late payment, etc.)"
      style={{background:'none',border:'1px dashed #D1D5DB',borderRadius:4,padding:'1px 6px',cursor:'pointer',fontSize:10,color:'#94A3B8'}}>
      + Note
    </button>
  );
  if (editing) return (
    <input autoFocus value={val} onChange={e=>setVal(e.target.value)}
      onBlur={()=>{onSave(val);setEditing(false);}}
      onKeyDown={e=>{if(e.key==='Enter'){onSave(val);setEditing(false);}if(e.key==='Escape')setEditing(false);}}
      placeholder="Note for biller..."
      style={{fontSize:10,padding:'2px 6px',border:'1px solid #BFDBFE',borderRadius:4,outline:'none',minWidth:140}}/>
  );
  return (
    <span onClick={()=>setEditing(true)} style={{fontSize:10,color:'#475569',fontStyle:'italic',cursor:'pointer'}} title="Click to edit note">
      📝 {val}
    </span>
  );
}


// ── History ───────────────────────────────────────────────────────────────────
function HistorySection({entries,billingEntries}) {
  const [search,setSearch]=useState('');
  const [filter,setFilter]=useState('thisweek');
  const [expanded,setExpanded]=useState({});
  const [expandedRow,setExpandedRow]=useState({});

  const now=new Date();
  const weekStart=(d)=>{const s=new Date(d);s.setDate(s.getDate()-s.getDay());return s.toISOString().slice(0,10);};
  const thisWeek=weekStart(now);
  const lastWeek=weekStart(new Date(now.getFullYear(),now.getMonth(),now.getDate()-7));
  const thisMonth=now.toISOString().slice(0,7);
  const lastMonth=new Date(now.getFullYear(),now.getMonth()-1,1).toISOString().slice(0,7);

  // Merge billingEntries that have no matching doctorLog entry (exact date+name match)
  const merged=useMemo(()=>{
    const docDates=new Set(entries.map(e=>(e.date||'')+'|'+(e.patientName||'').toLowerCase().trim()));
    const billerOnly=(billingEntries||[]).filter(b=>{
      if(!b.patientName?.trim()) return false;
      const key=(b.date||'')+'|'+(b.patientName||'').toLowerCase().trim();
      // Also check loose match — last name match on same date
      const bLast=(b.patientName||'').toLowerCase().split(/[\s,]+/).filter(Boolean)[0]||'';
      const hasLooseMatch=entries.some(e=>e.date===b.date&&
        (e.patientName||'').toLowerCase().split(/[\s,]+/).some(p=>p===bLast&&bLast.length>2));
      return !docDates.has(key)&&!hasLooseMatch;
    }).map(b=>({...b,_billerAdded:true}));
    return [...entries,...billerOnly];
  },[entries,billingEntries]);

  const filtered=useMemo(()=>merged.filter(e=>{
    if(search&&!e.patientName?.toLowerCase().includes(search.toLowerCase())) return false;
    const d=e.date||'';
    if(filter==='thisweek') return d>=thisWeek;
    if(filter==='lastweek') return d>=lastWeek&&d<thisWeek;
    if(filter==='thismonth') return d.startsWith(thisMonth);
    if(filter==='lastmonth') return d.startsWith(lastMonth);
    return true;
  }).sort((a,b)=>(b.date||'').localeCompare(a.date||'')),[merged,search,filter,thisWeek,lastWeek,thisMonth,lastMonth]);

  // Group by date (day)
  const grouped=useMemo(()=>{
    const g={};
    for(const e of filtered){const d=e.date||today();if(!g[d])g[d]=[];g[d].push(e);}
    return Object.entries(g).sort((a,b)=>b[0].localeCompare(a[0]));
  },[filtered]);

  // Optos % by month
  const optosByMonth=useMemo(()=>{
    const months={};
    for(const e of entries){
      if (!e.date) continue;
      const m=e.date.slice(0,7);
      if(!months[m]) months[m]={total:0,withOptos:0};
      if(e.entryType!=='admin') {
        months[m].total++;
        if(parseFloat(e.optos)>0||parseFloat(e.oct)>0) months[m].withOptos++;
      }
    }
    return Object.entries(months).sort((a,b)=>b[0].localeCompare(a[0])).slice(0,6);
  },[entries]);

  const inp={padding:'6px 10px',border:'1px solid #E2E8F0',borderRadius:6,fontSize:12,fontFamily:"'DM Sans',sans-serif",outline:'none'};

  return (
    <div style={{marginTop:24}}>
      <h2 style={{fontFamily:"'DM Serif Display',serif",fontSize:16,color:'#1B3A5C',marginBottom:10}}>History</h2>

      {/* Optos % — quiet inline line */}
      {optosByMonth.length>0&&(
        <div style={{fontSize:10,color:'#94A3B8',marginBottom:12}}>
          Optos: {optosByMonth.map(([m,stats])=>{
            const pct=stats.total>0?Math.round(stats.withOptos/stats.total*100):0;
            const [yr,mo]=m.split('-');
            const label=new Date(parseInt(yr),parseInt(mo)-1,1).toLocaleString('en-US',{month:'short'});
            return <span key={m} style={{marginRight:10}}>{label} {yr.slice(2)}: <strong style={{color:pct>=50?'#1D4ED8':'#94A3B8'}}>{pct}%</strong></span>;
          })}
        </div>
      )}

      {/* Filters */}
      <div style={{display:'flex',gap:8,marginBottom:12,flexWrap:'wrap',alignItems:'center'}}>
        <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search patient..." style={{...inp,width:160}}/>
        {[['thisweek','This Week'],['lastweek','Last Week'],['thismonth','This Month'],['lastmonth','Last Month'],['all','All']].map(([v,l])=>(
          <button key={v} onClick={()=>setFilter(v)}
            style={{background:filter===v?'#1B3A5C':'#F1F5F9',color:filter===v?'white':'#64748B',border:'none',borderRadius:6,padding:'5px 10px',cursor:'pointer',fontSize:11,fontWeight:filter===v?700:400}}>
            {l}
          </button>
        ))}
        <span style={{fontSize:11,color:'#94A3B8',marginLeft:'auto'}}>{filtered.length} entries</span>
      </div>

      {grouped.length===0&&<div style={{fontSize:12,color:'#94A3B8',textAlign:'center',padding:'20px 0'}}>No entries found.</div>}

      {grouped.map(([date,dayEntries])=>{
        const isOpen=expanded[date]!==false;
        const paid=dayEntries.filter(e=>e.entryType!=='admin');
        const dayPtTotal=paid.reduce((s,e)=>s+calcPtPaid(e),0);
        const dayInsTotal=paid.reduce((s,e)=>s+calcInsPaid(e),0);
        const dayTotal=dayPtTotal+dayInsTotal;
        return (
          <div key={date} style={{marginBottom:6,border:'1px solid #E2E8F0',borderRadius:8,overflow:'hidden'}}>
            {/* Day header */}
            <div onClick={()=>setExpanded(p=>({...p,[date]:!isOpen}))}
              style={{display:'flex',gap:8,padding:'7px 12px',background:'#F8FAFC',cursor:'pointer',userSelect:'none',alignItems:'center'}}>
              <span style={{fontSize:9,color:'#94A3B8'}}>{isOpen?'▼':'▶'}</span>
              <span style={{fontSize:12,fontWeight:600,color:'#1B3A5C'}}>{dayAbb(date)} {fmtShort(date)}</span>
              <span style={{fontSize:11,color:'#94A3B8'}}>{paid.length} patients</span>
              {/* Gross total — not emphasized */}
              {dayTotal>0&&<span style={{fontSize:10,color:'#94A3B8',marginLeft:'auto'}}>{fmt$(dayTotal)}</span>}
            </div>
            {isOpen&&(
              <table style={{width:'100%',borderCollapse:'collapse',fontSize:10}}>
                <thead>
                  <tr style={{background:'#F8FAFC',borderBottom:'2px solid #E2E8F0'}}>
                    <th style={{padding:'4px 8px',fontSize:8,fontWeight:700,color:'#64748B',textTransform:'uppercase',textAlign:'left',whiteSpace:'nowrap'}}>Patient</th>
                    <th style={{padding:'4px 8px',fontSize:8,fontWeight:700,color:'#64748B',textTransform:'uppercase',textAlign:'left',whiteSpace:'nowrap',width:200}}>Services</th>
                    <th style={{padding:'4px 8px',fontSize:8,fontWeight:700,color:'#64748B',textTransform:'uppercase',textAlign:'right',whiteSpace:'nowrap'}}>Pt Paid</th>
                    <th style={{padding:'4px 8px',fontSize:8,fontWeight:700,color:'#64748B',textTransform:'uppercase',textAlign:'right',whiteSpace:'nowrap'}}>Ins Exp</th>
                    <th style={{padding:'4px 8px',fontSize:8,fontWeight:700,color:'#64748B',textTransform:'uppercase',textAlign:'left',whiteSpace:'nowrap'}}>Payor</th>
                    <th style={{padding:'4px 8px',fontSize:8,fontWeight:700,color:'#64748B',textTransform:'uppercase',textAlign:'left',width:'100%'}}>Notes</th>
                    <th style={{padding:'4px 8px',whiteSpace:'nowrap'}}></th>
                  </tr>
                </thead>
                <tbody>
                  {dayEntries.sort((a,b)=>(a.createdAt||'').localeCompare(b.createdAt||'')).map((e,i)=>{
                    const ptPaid=calcPtPaid(e);
                    const insPaid=calcInsPaid(e);
                    const insExp=parseFloat(e.ins)||0;
                    const total=ptPaid+(insPaid>0?insPaid:insExp);
                    const isSelf=/self|oop|out.of.pocket/i.test(e.payor1||'');
                    const bMatch=findBillingMatch(e,billingEntries);
                    const isRowOpen=expandedRow[e.id];
                    return (
                      <React.Fragment key={e.id}>
                        <tr style={{borderBottom:'1px solid #F0F4F8',background:i%2===0?'white':'#FAFBFC',cursor:'pointer'}}
                          onClick={()=>setExpandedRow(p=>({...p,[e.id]:!isRowOpen}))}>
                          <td style={{padding:'4px 8px',fontWeight:600,color:'#1B3A5C',whiteSpace:'nowrap'}}>
                            {e.patientName}
                            {e.entryType==='followup'&&<span style={{marginLeft:4,fontSize:8,color:'#92400E',background:'#FEF3C7',borderRadius:3,padding:'0 3px'}}>Unpaid</span>}
                            {e.attn&&<span style={{marginLeft:4,fontSize:13,color:'#F59E0B'}} title={e.attn}>★</span>}
                            {(()=>{const bm=findBillingMatch(e,billingEntries);const err=parseFloat(bm?.paymentErrorLoss)||0;return err>0?<span style={{marginLeft:4,fontSize:9,background:'#FEE2E2',color:'#DC2626',borderRadius:3,padding:'1px 4px',fontWeight:700}}>⚠ {fmt$(err)}</span>:null;})()}
                          </td>
                          <td style={{padding:'4px 8px',color:'#475569',width:200,maxWidth:200,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}
                            title={['exam','cl','optos','oct','dfe','ov'].filter(k=>parseFloat(e[k])>0).map(k=>`${k}:${fmt$(e[k])}`).join(' ')+(parseFloat(e.myopia)>0?` myopia:${fmt$(e.myopia)}`:''+(parseFloat(e.otherAmt)>0?` ${e.otherType||'other'}:${fmt$(e.otherAmt)}`:''))}>
                            {['exam','cl','optos','oct','dfe','ov'].filter(k=>parseFloat(e[k])>0).map(k=>`${k}:${fmt$(e[k])}`).join(' ')}
                            {parseFloat(e.myopia)>0?` myopia:${fmt$(e.myopia)}`:''}
                            {parseFloat(e.otherAmt)>0?` ${e.otherType||'other'}:${fmt$(e.otherAmt)}`:''}
                          </td>
                          <td style={{padding:'4px 8px',fontWeight:700,color:'#16A34A',textAlign:'right',whiteSpace:'nowrap'}}>{ptPaid>0?fmt$(ptPaid):'$0'}</td>
                          <td style={{padding:'4px 8px',color:insPaid>0?'#065F46':'#94A3B8',textAlign:'right',whiteSpace:'nowrap'}}>{isSelf?'$0':insPaid>0?fmt$(insPaid):insExp>0?<span style={{opacity:0.5}}>{fmt$(insExp)}</span>:'—'}</td>
                          <td style={{padding:'4px 8px',color:'#64748B',whiteSpace:'nowrap',fontSize:9}}>{e.payor1||'—'}</td>
                          <td style={{padding:'4px 8px',color:'#94A3B8',fontStyle:'italic',fontSize:10,maxWidth:150,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}} title={e.notes}>{e.notes}</td>
                          <td style={{padding:'4px 6px',fontSize:9,color:'#94A3B8'}}>{isRowOpen?'▲':'▼'}</td>
                        </tr>
                        {isRowOpen&&(
                          <tr style={{background:'#F8FAFC',borderBottom:'1px solid #E2E8F0'}}>
                            <td colSpan={7} style={{padding:'8px 16px'}}>
                              <div style={{display:'flex',gap:16,flexWrap:'wrap',fontSize:11}}>
                                {/* Full service breakdown */}
                                <div>
                                  <div style={{fontSize:9,fontWeight:700,color:'#64748B',textTransform:'uppercase',marginBottom:4}}>Services</div>
                                  <div style={{display:'flex',gap:8,flexWrap:'wrap'}}>
                                    {['exam','cl','optos','oct','dfe','ov','myopia'].filter(k=>parseFloat(e[k])>0).map(k=>(
                                      <span key={k} style={{color:'#475569'}}>{k}: <strong>{fmt$(e[k])}</strong></span>
                                    ))}
                                    {parseFloat(e.otherAmt)>0&&<span style={{color:'#475569'}}>{e.otherType||'Other'}: <strong>{fmt$(e.otherAmt)}</strong></span>}
                                  </div>
                                </div>
                                {/* Discount */}
                                {parseFloat(e.discountAmount)>0&&(
                                  <div>
                                    <div style={{fontSize:9,fontWeight:700,color:'#64748B',textTransform:'uppercase',marginBottom:4}}>Discount</div>
                                    <span style={{color:'#DC2626'}}>{e.discountType||'Disc'}: <strong>-{fmt$(e.discountAmount)}</strong></span>
                                  </div>
                                )}
                                {/* Insurance */}
                                {(e.payor1||e.payor2)&&(
                                  <div>
                                    <div style={{fontSize:9,fontWeight:700,color:'#64748B',textTransform:'uppercase',marginBottom:4}}>Insurance</div>
                                    <div style={{display:'flex',gap:8}}>
                                      {e.payor1&&<span>{e.payor1} exp:{fmt$(e.ins1Amt)} {insPaid>0?<span style={{color:'#065F46'}}>paid:{fmt$(e.insurancePaid1)}</span>:''}</span>}
                                      {e.payor2&&<span>{e.payor2} exp:{fmt$(e.ins2Amt)}</span>}
                                    </div>
                                  </div>
                                )}
                                {/* Claims */}
                                {(e.claimNumber||e.claimNumber2)&&(
                                  <div>
                                    <div style={{fontSize:9,fontWeight:700,color:'#64748B',textTransform:'uppercase',marginBottom:4}}>Claims</div>
                                    {e.claimNumber&&<span style={{color:'#475569'}}>#{e.claimNumber}</span>}
                                    {e.claimNumber2&&<span style={{color:'#475569',marginLeft:6}}>#{e.claimNumber2}</span>}
                                  </div>
                                )}
                                {/* Billing note */}
                                {bMatch?.notes&&(
                                  <div>
                                    <div style={{fontSize:9,fontWeight:700,color:'#1D4ED8',textTransform:'uppercase',marginBottom:4}}>Billing Note</div>
                                    <span style={{color:'#1D4ED8',fontStyle:'italic'}}>{bMatch.notes}</span>
                                  </div>
                                )}
                              </div>
                            </td>
                          </tr>
                        )}
                      </React.Fragment>
                    );
                  })}
                </tbody>
                {/* Day totals */}
                {paid.length>0&&(
                  <tfoot>
                    <tr style={{borderTop:'2px solid #E2E8F0',background:'#F0FDF4'}}>
                      <td colSpan={2} style={{padding:'4px 8px',fontSize:10,color:'#1B3A5C',fontWeight:600}}>{paid.length} patients</td>
                      <td style={{padding:'4px 8px',fontSize:10,color:'#16A34A',textAlign:'right',fontWeight:700}}>{fmt$(dayPtTotal)}</td>
                      <td style={{padding:'4px 8px',fontSize:10,color:'#065F46',textAlign:'right'}}>{dayInsTotal>0?fmt$(dayInsTotal):'—'}</td>
                      <td style={{padding:'4px 8px',fontSize:10,color:'#1B3A5C',textAlign:'right',fontWeight:800}}>{fmt$(dayTotal)}</td>
                      <td colSpan={2}></td>
                    </tr>
                  </tfoot>
                )}
              </table>
            )}
          </div>
        );
      })}
    </div>
  );
}

// ── Main ──────────────────────────────────────────────────────────────────────
export default function DoctorLog({user,profile}) {
  const [entries,setEntries]=useState([]);
  const [rows,setRows]=useState([]);
  const [billingEntries,setBillingEntries]=useState([]);
  const [loading,setLoading]=useState(true);
  const [filterDate,setFilterDate]=useState(today());
  const [filterLoc,setFilterLoc]=useState('');
  const [tooltips,setTooltips]=useState({});
  const [editEntry,setEditEntry]=useState(null);
  const [showChangePw,setShowChangePw]=useState(false);
  const [newPw,setNewPw]=useState('');
  const [pwMsg,setPwMsg]=useState('');
  const [showPaste,setShowPaste]=useState(false);
  const [pasteText,setPasteText]=useState('');
  const [otherItems,setOtherItems]=useState([]);
  const [submitted,setSubmitted]=useState(false);
  const [showBillingCols,setShowBillingCols]=useState(()=>localStorage.getItem('doclog_billing_cols')==='true');
  const [insOpenRows,setInsOpenRows]=useState({});
  const doctorId=profile.doctorId||profile.uid;

  const blank=useCallback(()=>emptyEntry(doctorId,profile.name,filterDate||today(),filterLoc||''),[doctorId,profile.name,filterDate,filterLoc]);

  useEffect(()=>{
    async function load(){
      try{
        const [logSnap,billingSnap,settingsSnap]=await Promise.all([
          getDocs(query(collection(db,'doctorLogs'),where('doctorId','==',doctorId))),
          getDocs(query(collection(db,'billingEntries'),where('doctorId','==',doctorId))),
          getDoc(doc(db,'billingSettings','otherItems'))
        ]);
        setEntries(logSnap.docs.map(d=>({id:d.id,...d.data()})));
        setBillingEntries(billingSnap.docs.map(d=>({id:d.id,...d.data()})));
        if(settingsSnap.exists()) setOtherItems(settingsSnap.data().items||[]);
      }catch(e){console.error(e);}
      setLoading(false);
    }
    load();
  },[doctorId]);

  useEffect(()=>{
    setSubmitted(false);
    const relevant=entries.filter(e=>{
      if(filterDate&&e.date!==filterDate) return false;
      if(filterLoc&&e.location!==filterLoc) return false;
      return true;
    }).sort((a,b)=>(a.createdAt||'').localeCompare(b.createdAt||''));
    setRows(relevant.length>0?relevant:[blank()]);
  },[filterDate,filterLoc,entries]); // eslint-disable-line

  const handleSave=useCallback((entry)=>{
    setEntries(prev=>{const i=prev.findIndex(e=>e.id===entry.id);if(i>=0){const n=[...prev];n[i]=entry;return n;}return[...prev,entry];});
    setRows(prev=>{const i=prev.findIndex(e=>e.id===entry.id);if(i>=0){const n=[...prev];n[i]=entry;return n;}return prev;});
  },[]);

  const [undoStack,setUndoStack]=useState([]); // [{entry, timer}]
  const handleDelete=(id)=>{
    const deleted=rows.find(e=>e.id===id);
    if(!deleted) return;
    // Remove from UI immediately
    setRows(prev=>{const f=prev.filter(e=>e.id!==id);return f.length>0?f:[blank()];});
    setEntries(prev=>prev.filter(e=>e.id!==id));
    // Add to undo stack
    const timer=setTimeout(async()=>{
      // Permanently delete after 10s
      await deleteDoc(doc(db,'doctorLogs',id)).catch(()=>{});
      setUndoStack(prev=>prev.filter(u=>u.id!==id));
    },10000);
    setUndoStack(prev=>[...prev,{...deleted,timer}]);
  };
  const handleUndo=(id)=>{
    const item=undoStack.find(u=>u.id===id);
    if(!item) return;
    clearTimeout(item.timer);
    setUndoStack(prev=>prev.filter(u=>u.id!==id));
    const {timer:_,...restored}=item;
    setRows(prev=>[...prev,restored].sort((a,b)=>(a.createdAt||'').localeCompare(b.createdAt||'')));
    setEntries(prev=>[...prev,restored]);
  };

  const insertAfter=(idx)=>setRows(prev=>{const r=[...prev];r.splice(idx+1,0,blank());return r;});
  const appendRow=()=>setRows(prev=>[...prev,blank()]);

  const handlePaste=async()=>{
    const names=parseScheduleText(pasteText);
    if(!names.length){alert('No patient names found. Paste the TAB schedule directly.');return;}
    const now=Date.now();
    const newRows=names.map((name,i)=>({...blank(),id:uid(),patientName:name,createdAt:new Date(now+i).toISOString()}));
    await Promise.all(newRows.map(r=>setDoc(doc(db,'doctorLogs',r.id),r)));
    newRows.forEach(r=>setEntries(prev=>[...prev,r]));
    setRows(prev=>[...prev.filter(r=>r.patientName?.trim()),...newRows]);
    setShowPaste(false);setPasteText('');
  };

  const handleChangePw=async()=>{
    if(!newPw||newPw.length<6){setPwMsg('Password must be at least 6 characters.');return;}
    try{await changePassword(newPw);setPwMsg('Password changed!');setNewPw('');setTimeout(()=>{setPwMsg('');setShowChangePw(false);},2000);}
    catch(e){setPwMsg('Error: '+e.message);}
  };

  const inp={padding:'7px 10px',border:'1.5px solid #E2E8F0',borderRadius:7,fontSize:13,fontFamily:"'DM Sans',sans-serif",outline:'none',background:'white'};
  const hdrs=['Loc','Day','Date','Patient','Unpaid','Exam','CL','Optos','OCT','DFE','OV','Myopia','Other $','Other','Disc $','Disc','Pt Paid','Total','Ins $','Payor','Notes',''];
  const DOCLOG_COL_KEY='spark_col_widths_doclog';
  const colWidthsRef=React.useRef(JSON.parse(localStorage.getItem(DOCLOG_COL_KEY)||'{}'));
  const onDocColResize=(e,idx)=>{
    e.preventDefault();
    const startX=e.clientX,startW=e.target.parentElement.offsetWidth;
    const onMove=(ev)=>{
      const newW=Math.max(20,startW+(ev.clientX-startX));
      colWidthsRef.current[idx]=newW;
      const th=document.querySelectorAll('.doclog-th')[idx];
      if(th)th.style.width=newW+'px';
    };
    const onUp=()=>{
      localStorage.setItem(DOCLOG_COL_KEY,JSON.stringify(colWidthsRef.current));
      document.removeEventListener('mousemove',onMove);
      document.removeEventListener('mouseup',onUp);
    };
    document.addEventListener('mousemove',onMove);
    document.addEventListener('mouseup',onUp);
  };
  const todayRows=rows.filter(r=>r.patientName?.trim());
  const historyEntries=filterDate?entries.filter(e=>e.date!==filterDate):entries;

  if(loading) return <div style={{padding:40,textAlign:'center',color:'#94A3B8',fontFamily:"'DM Sans',sans-serif"}}>Loading…</div>;

  return (
    <div style={{maxWidth:1300,margin:'0 auto',padding:'20px 16px',fontFamily:"'DM Sans',sans-serif"}}>
      {/* Header */}
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:14,flexWrap:'wrap',gap:10}}>
        <h1 style={{fontFamily:"'DM Serif Display',serif",fontSize:22,color:'#1B3A5C',margin:0}}>My Patient Log — {profile.name}</h1>
        <button onClick={()=>setShowChangePw(v=>!v)} style={{background:'#F1F5F9',color:'#64748B',border:'none',borderRadius:7,padding:'6px 10px',cursor:'pointer',fontSize:12}}>🔑 Change Password</button>
      </div>
      {/* Today's date banner */}
      <div style={{background:'#EFF6FF',borderRadius:8,padding:'8px 14px',marginBottom:12}}>
        <span style={{fontSize:13,fontWeight:700,color:'#1D4ED8'}}>📅 Today is {['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][new Date().getDay()]}, {new Date().toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}</span>
      </div>

      {/* Change PW */}
      {showChangePw&&(
        <div style={{background:'white',borderRadius:10,padding:'12px 16px',marginBottom:12,border:'1px solid #E2E8F0',display:'flex',gap:10,alignItems:'center',flexWrap:'wrap'}}>
          <input type="password" value={newPw} onChange={e=>setNewPw(e.target.value)} placeholder="New password (min 6 chars)" style={{...inp,width:220,fontSize:12}}/>
          <button onClick={handleChangePw} style={{background:'#10B981',color:'white',border:'none',borderRadius:7,padding:'6px 14px',cursor:'pointer',fontSize:12,fontWeight:600}}>Update</button>
          <button onClick={()=>setShowChangePw(false)} style={{background:'#F1F5F9',color:'#64748B',border:'none',borderRadius:7,padding:'6px 10px',cursor:'pointer',fontSize:11}}>Cancel</button>
          {pwMsg&&<span style={{fontSize:12,color:pwMsg.includes('Error')?'#DC2626':'#10B981',fontWeight:600}}>{pwMsg}</span>}
        </div>
      )}

      {/* Filters */}
      <div style={{display:'flex',gap:8,marginBottom:10,alignItems:'center',flexWrap:'wrap'}}>
        <div style={{display:'flex',alignItems:'center',gap:5}}>
          {filterDate&&<span style={{fontSize:12,fontWeight:700,color:'#1B3A5C',minWidth:28}}>{dayAbb(filterDate)}</span>}
          <input type="date" value={filterDate} onChange={e=>setFilterDate(e.target.value)} style={{...inp,fontSize:12,padding:'5px 8px'}}/>
        </div>
        <select value={filterLoc} onChange={e=>setFilterLoc(e.target.value)} style={{...inp,fontSize:12,padding:'5px 8px'}}>
          <option value="">All Locations</option>
          {LOCATIONS.map(l=><option key={l} value={l}>{l} — {LOC_FULL[l]}</option>)}
        </select>
        <button onClick={()=>setShowPaste(v=>!v)} style={{background:'#EFF6FF',color:'#1D4ED8',border:'1px solid #BFDBFE',borderRadius:7,padding:'5px 12px',cursor:'pointer',fontSize:11,fontWeight:600}}
          title="Highlight and copy your entire TAB schedule, then paste here">
          📋 Paste Schedule
        </button>
        {tooltips.pasteSchedule&&<InfoTooltip text={tooltips.pasteSchedule}/>}
        <DocSquarePanel date={filterDate} loc={filterLoc} rows={todayRows} inline={true}/>
        <span style={{fontSize:11,color:'#94A3B8',marginLeft:'auto'}}>{todayRows.length} entries</span>
      </div>
      <div style={{fontSize:10,color:'#94A3B8',fontStyle:'italic',marginBottom:8}}>
        Rows save automatically as you type · Check "Unpaid" for follow-ups or visits with no charge · Leave ins $ blank if not billing insurance
      </div>

      {/* Paste */}
      {showPaste&&(
        <div style={{background:'#EFF6FF',border:'1px solid #BFDBFE',borderRadius:10,padding:'12px 16px',marginBottom:12}}>
          <p style={{fontSize:12,color:'#1D4ED8',fontWeight:600,marginBottom:6}}>Paste TAB schedule — names extracted in order</p>
          <textarea value={pasteText} onChange={e=>setPasteText(e.target.value)} rows={5} placeholder="Paste schedule here..."
            style={{width:'100%',fontSize:11,fontFamily:'monospace',border:'1px solid #BFDBFE',borderRadius:6,padding:'6px 8px',resize:'vertical',boxSizing:'border-box'}}/>
          <div style={{display:'flex',gap:8,marginTop:8}}>
            <button onClick={handlePaste} style={{background:'#1D4ED8',color:'white',border:'none',borderRadius:6,padding:'6px 14px',cursor:'pointer',fontSize:12,fontWeight:600}}>Generate rows</button>
            <button onClick={()=>{setShowPaste(false);setPasteText('');}} style={{background:'#F1F5F9',border:'none',borderRadius:6,padding:'6px 10px',cursor:'pointer',fontSize:12,color:'#64748B'}}>Cancel</button>
          </div>
        </div>
      )}

      {/* Undo toast — below table */}
      {undoStack.length>0&&(
        <div style={{display:'flex',flexDirection:'column',gap:6,marginTop:6}}>
          {undoStack.map(item=>(
            <div key={item.id} style={{background:'#1B3A5C',color:'white',borderRadius:8,padding:'6px 14px',display:'inline-flex',alignItems:'center',gap:12,fontSize:11,alignSelf:'flex-start'}}>
              <span>Row deleted</span>
              <button onClick={()=>handleUndo(item.id)}
                style={{background:'#F59E0B',color:'white',border:'none',borderRadius:5,padding:'2px 10px',cursor:'pointer',fontSize:11,fontWeight:700}}>
                ↩ Undo
              </button>
            </div>
          ))}
        </div>
      )}
      {/* Table */}
      <div>
        <table style={{width:'100%',borderCollapse:'collapse',fontSize:11,tableLayout:'fixed'}}>

          <colgroup>
            <col style={{width:30}}/><col style={{width:24}}/><col style={{width:50}}/>
            <col style={{width:110}}/><col style={{width:36}}/>
            <col style={{width:32}}/><col style={{width:32}}/><col style={{width:36}}/>
            <col style={{width:32}}/><col style={{width:30}}/><col style={{width:30}}/><col style={{width:36}}/>
            <col style={{width:36}}/><col style={{width:64}}/><col style={{width:32}}/><col style={{width:64}}/>
            <col style={{width:46}}/><col style={{width:46}}/>
            <col style={{width:36}}/><col style={{width:54}}/>
            <col/><col style={{width:86}}/>
          </colgroup>
          <thead>
            <tr style={{borderBottom:'2px solid #E2E8F0',background:'#F8FAFC'}}>
              {hdrs.map((h,i)=>(
                <th key={i} className="doclog-th"
                  style={{padding:'3px 2px',fontSize:h==='★'?12:9,fontWeight:700,color:h==='P1$'||h==='P1'?'#1D4ED8':'#64748B',textTransform:'uppercase',
                    textAlign:'center',
                    whiteSpace:'nowrap',position:'relative',userSelect:'none',
                    ...(colWidthsRef.current[i]?{width:colWidthsRef.current[i]}:{})
                  }}>
                  {h}
                  {i < hdrs.length-1 && <span onMouseDown={e=>onDocColResize(e,i)}
                    style={{position:'absolute',right:0,top:0,bottom:0,width:4,cursor:'col-resize',background:'transparent'}}
                    onMouseOver={e=>e.currentTarget.style.background='#CBD5E1'}
                    onMouseOut={e=>e.currentTarget.style.background='transparent'}/> }
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((entry,i)=>(
              <DocRow key={entry.id} entry={entry} idx={i}
                onSave={handleSave} onDelete={handleDelete}
                onInsertAfter={()=>insertAfter(i)} onEdit={setEditEntry}
                otherItems={otherItems}
                insOpen={insOpenRows[entry.id]||false}
                onToggleIns={()=>setInsOpenRows(p=>({...p,[entry.id]:!p[entry.id]}))}
                billingMatch={findBillingMatch(entry,billingEntries)}/>
            ))}
          </tbody>
        </table>
      </div>

      {/* Add row + Submit */}
      <div style={{display:'flex',alignItems:'center',gap:12,marginTop:8}}>
        <button onClick={appendRow} style={{background:'#F0FDF4',border:'1px solid #BBF7D0',borderRadius:6,padding:'4px 12px',cursor:'pointer',fontSize:11,color:'#16A34A',fontWeight:600}}>+ Add row</button>
        {submitted?(
          <span style={{fontSize:12,color:'#065F46',fontWeight:600}}>✅ Submitted!</span>
        ):(
          <button onClick={()=>setSubmitted(true)}
            style={{background:'#F0FDF4',color:'#065F46',border:'1px solid #6EE7B7',borderRadius:7,padding:'5px 14px',cursor:'pointer',fontSize:11,fontWeight:600}}>
            ✓ Submit Day
          </button>
        )}
      </div>

      {/* History */}
      <HistorySection entries={historyEntries} billingEntries={billingEntries}/>

      {/* Edit modal */}
      {editEntry&&<EditModal formData={editEntry} onSave={e=>{handleSave(e);setEditEntry(null);}} onClose={()=>setEditEntry(null)} otherItems={otherItems}/>}
    </div>
  );
}
